/* ---------- Helpers ---------- */
function getLang(){
  const stored = (typeof localStorage !== 'undefined') ? localStorage.getItem('kidsbingo-lang') : null;
  if(stored && SUPPORTED_LANGUAGES.some(l => l.code === stored)) return stored;
  return DEFAULT_LANG;
}
function setLang(code){
  if(typeof localStorage !== 'undefined') localStorage.setItem('kidsbingo-lang', code);
}
function langMeta(code){
  return SUPPORTED_LANGUAGES.find(l => l.code === code) || SUPPORTED_LANGUAGES[0];
}
function t(key, vars){
  const lang = getLang();
  const entry = UI_STRINGS[key];
  if(!entry) return key;
  let str = entry[lang] || entry[DEFAULT_LANG] || key;
  if(vars){
    Object.keys(vars).forEach(k => { str = str.replace('{' + k + '}', vars[k]); });
  }
  return str;
}
function themeLabel(theme, lang){
  lang = lang || getLang();
  if(lang === 'nl') return theme.label;
  const entry = THEME_LABEL_I18N[theme.id];
  return (entry && entry[lang]) || theme.label;
}
function variantLabel(variant, lang){
  lang = lang || getLang();
  if(lang === 'nl') return variant.label;
  const entry = VARIANT_LABEL_I18N[variant.id];
  return (entry && entry[lang]) || variant.label;
}
function variantDescription(variant, lang){
  lang = lang || getLang();
  if(lang === 'nl') return variant.description;
  const entry = VARIANT_DESC_I18N[variant.id];
  return (entry && entry[lang]) || variant.description;
}
function itemLabel(item, lang){
  lang = lang || getLang();
  if(lang === 'nl') return item.label;
  const entry = ITEM_LABEL_I18N[item.id];
  return (entry && entry[lang]) || item.label;
}
